CREATE TABLE asset_version (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,brand_id uuid NOT NULL,revision_id uuid NOT NULL,storage_key text NOT NULL UNIQUE,checksum text NOT NULL,mime text NOT NULL DEFAULT 'image/png',width int NOT NULL,height int NOT NULL,rights text NOT NULL DEFAULT 'INTERNAL_TEMPLATE',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(revision_id),FOREIGN KEY(revision_id,brand_id,workspace_id) REFERENCES content_revision(id,brand_id,workspace_id));
